  } else if (character === '"' && value.length === 0) {
    inQuotes = true;
    quoted = true;
  } else if (character === ",") {
    values.push(quoted ? value : value.trim());
    value = "";
    quoted = false;
  } else {
    value += character;
  }
}

values.push(quoted ? value : value.trim());
return values;

