export function normalizeStorageKey(value: string): string | null {
  let decoded: string;

  try {
    decoded = decodeURIComponent(value);
  } catch {
    return null;
  }

  const isUnsafePath = (path: string) => {
    const normalized = path.replaceAll("\\", "/");

    return (
      normalized.startsWith("/") ||
      /^[A-Za-z]:\//.test(normalized) ||
      normalized.split("/").some((segment) => segment === "..")
    );
  };

  let encodedPath = decoded;
  while (/%[0-9A-Fa-f]{2}/.test(encodedPath)) {
    try {
      encodedPath = decodeURIComponent(encodedPath);
    } catch {
      break;
    }

    if (isUnsafePath(encodedPath)) {
      return null;
    }
  }

  if (isUnsafePath(decoded)) {
    return null;
  }

  const key = decoded
    .replaceAll("\\", "/")
    .split("/")
    .filter((segment) => segment && segment !== ".")
    .join("/");

  return key || null;
}

