    normalized.split("/").some((segment) => segment === "..")
  ) {
    return true;
  }

  if (/%[0-9A-Fa-f]{2}/.test(path)) {
    try {
      const furtherDecoded = decodeURIComponent(path);
      return furtherDecoded !== path && hasTraversal(furtherDecoded);
